import test from 'node:test';
import assert from 'node:assert/strict';
import { simulate, worldFor, WEEKS } from './engine.js';
test('effort is finite, output bounded, and different plans face the same world', () => { const a = simulate(), b = simulate({ plan: Array(20).fill(7) }); assert.deepEqual(a.history.map(r => r.world), b.history.map(r => r.world)); for (const row of [...a.history, ...b.history]) { assert.equal(row.research + row.build, 10); assert.ok(row.useful >= 0 && row.useful <= row.build); } assert.deepEqual(simulate(), a); });
test('research alone cannot teach technical knowledge or create output', () => { const run = simulate({ plan: Array(20).fill(10) }); assert.equal(run.final.value, 0); assert.equal(run.final.belief.technical, 0.5); assert.ok(run.final.needError < 0.05); });
test('shipping teaches, but only after the feedback delay', () => { const run = simulate({ plan: Array(20).fill(0), assumptions: { delay: 4, usefulness: 1 } }); assert.ok(run.history.slice(0, 4).every(row => row.belief.technical === 0.5)); assert.ok(run.history[4].evidence.some(item => item.source === 'delivery' && item.from === 1)); assert.notEqual(run.history[4].belief.technical, 0.5); assert.ok(run.final.technicalError < 0.05); });
test('useless research consumes effort without sneaking in hidden world knowledge', () => { const run = simulate({ plan: Array(20).fill(10), assumptions: { usefulness: 0, delay: 1 } }); for (const row of run.history) { assert.deepEqual(row.belief, { need: 0.5, technical: 0.5 }); assert.deepEqual(row.evidence, []); } });
test('environmental change is external and stale feedback can disagree with current reality', () => { const run = simulate({ scenario: 'change', plan: Array(20).fill(0), assumptions: { usefulness: 1, delay: 5 } }); assert.ok(worldFor('change', 10).need > 0.7); assert.ok(worldFor('change', 11).need < 0.35); const evidence = run.history[10].evidence[0]; assert.equal(evidence.from, 6); assert.ok(evidence.need > 0.7); });
test('research has opportunity cost: more is not universally better', () => { const ship = simulate({ plan: Array(WEEKS).fill(0) }); const research = simulate({ plan: Array(WEEKS).fill(9) }); assert.ok(ship.final.value > research.final.value); assert.ok(research.final.needError < ship.final.needError); });
